function importBook22(){const d=wxPanel(`<form id="book22"><h2>导入共读小说</h2><label>书名<input name="title" required maxlength="100"></label><label>上传 TXT<input id="txt22" type="file" accept=".txt,text/plain"></label><label>或粘贴正文<textarea name="text" rows="8"></textarea></label><p>单本最多200万字。自动识别“第X章”或Chapter标题；没有标题时每6000字分一节。TXT按UTF-8读取。</p><button class="primary full">加入书架</button></form>`);$('#book22').onsubmit=e=>{e.preventDefault();run22(async()=>{const f=e.target,file=$('#txt22').files[0];if(file?.size>8*1024*1024)throw Error('TXT最多8MB');const text=file?await file.text():f.text.value,chapters=U22.chapters(text);saveReading22({...reading22,books:[...reading22.books,{id:crypto.randomUUID(),title:f.title.value.trim(),chapters,index:0,partners:[],discussions:{}}]});d.close();read22()})}}
// Animated only when the actual HTML audio element is playing.
function musicWidget22(){const host=screen.querySelector('.desktop-page');if(!host||$('#musicWidget22'))return;const b=document.createElement('button');b.id='musicWidget22';b.className='music-widget22';b.innerHTML='<span class="record22">♫</span><span><b>一起听歌</b><small id="songLabel22">上传歌曲，让音乐陪着你</small></span><span id="musicPlay22">▶</span>';b.onclick=()=>{const a=$('#togetherAudio');if(musicCurrent&&!musicCurrent.embed&&a){a.paused?a.play().catch(e=>toast(e.message)):a.pause()}else if(musicLibrary.tracks.length)playSong(musicLibrary.tracks[0].id);else go('music')};host.querySelector('.desktop-apps').before(b);syncMusic22()}
function syncMusic22(){const b=$('#musicWidget22'),a=$('#togetherAudio');if(!b)return;b.classList.toggle('playing',!!a&&!a.paused&&!a.ended);$('#songLabel22').textContent=musicCurrent?.title||'上传歌曲，让音乐陪着你';$('#musicPlay22').textContent=a&&!a.paused?'Ⅱ':'▶'}
const desktop22=renderDesktop;renderDesktop=function(){desktop22();musicWidget22()};for(const e of ['play','pause','ended','emptied'])document.addEventListener(e,syncMusic22,true);
render();

const furniture22=flatFurnitureArt;flatFurnitureArt=function(list=FurnitureData.items){if(list===FurnitureData.items||list===FurnitureData.garden){const inside=list===FurnitureData.items;return `<image href="assets/furniture-${inside?'inside':'garden'}-22.webp" width="${inside?1448:1844}" height="1086"/>`}return furniture22(list)};
const warm22=()=>{for(const src of ['assets/sakura-home-exterior-v15.jpg','assets/sakura-garden-ext-v17.jpg','assets/doll-v17.webp']){const i=new Image();i.decoding='async';i.src=src}};if(!navigator.connection?.saveData){if(window.requestIdleCallback)requestIdleCallback(warm22,{timeout:8000});else setTimeout(warm22,3000)}

async function restoreBackup22(data){const old=await snapshot22();phoneLocked=true;controller?.abort();proactiveController?.abort();stopVoice();stopMusic();try{const songs=[];for(const[k,v]of data.songs)songs.push([k,await blob22(v)]);await write22(await mediaDB,'images',data.media);await write22(await songDB,'files',songs);for(const k of Object.keys(local22()))localStorage.removeItem(k);for(const[k,v]of Object.entries(data.local))localStorage.setItem(k,v)}catch(e){try{await write22(await mediaDB,'images',old.media);await write22(await songDB,'files',old.songs);for(const k of Object.keys(local22()))localStorage.removeItem(k);for(const[k,v]of Object.entries(old.local))localStorage.setItem(k,v);phoneLocked=false}catch{throw Error('恢复未完成，请使用刚才导出的当前存档重新导入')}throw e}}
